{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik olarak sonlandırılıp sonlandırılmadığı, sistem çalıştırılarak ve süreler beklenerek doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediği, olaylar tetiklenerek ve kayıtlar incelenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damplarının UTC cinsinden ve iç sistem saatinden üretildiğinin doğrulanması için olaylar oluşturulup kayıtların zaman bilgisi gözlemlenmelidir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin algılanıp algılanmadığı ve uyarıların gönderilip gönderilmediği, saldırı senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Parola ve tek kullanımlık kodların ekranda gizlendiğinin (maskelendiğinin) çalıştırılıp gözlemlenerek gösterilmesi yeterlidir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolan oturumlarda yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı, senaryolar çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Analiz"
      ],
      "rationale": "İletişim kanallarının gizliliği ve bütünlüğünün korunması, şifreleme yapılandırmasının ve protokolün analizi ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz, bozuk veya beklenmedik girdilerin sistemin reddedip reddetmediği, çeşitli girdi senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediği ve ayrıntılı bilginin yetkili personele iz kayıtlarında görünüp görünmediği, hata senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum süresi uzatılmasının engellenmesi, uyarı gösterimi, taslak kaydı ve veri kaybı olmadan devam etme akışının çalıştırılarak test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmadığının ve bot eşiği aşıldığında etkileşimsiz kanıt veya WCAG uyumlu sorgunun gösterildiğinin, bot simülasyonu ile test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edilmesi, belirsiz durumların bekletilmesi ve sorgulanmasının, KÖA entegrasyon senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirteçlerinde oturumun sınırlı kipte açılıp açılmadığı ve kişisel verilerin gizlendiğinin, farklı belirteç senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulanması, bildirim gönderimi ve ele geçirme kanıtında zorunlu değişikliğin, senaryolar çalıştırılarak test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilip, eski/ileri adımların ve tekrarların reddedildiğinin, zamanlanmış kod senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiği aşıldığında doğrulayıcının devre dışı bırakılması, hesap kurtarma akışı ve sayaç sıfırlamanın, başarısız giriş senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı AAL düzeylerinde hareketsizlik sonrası devam etme akışlarının (parola vs e-Devlet yönlendirme) ve oturum sırrı silinmesinin, oturum senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılması, kullanıcıya bildirim ve SIEM'e olay iletiminin, çoklu oturum senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "İzin verilmeyen dosya türlerinin, içerik imzası uyuşmazlıklarının ve boyut/sayı limitlerinin reddedilip reddedilmediğinin, çeşitli dosya yükleme senaryolarıyla test edilmesi gerekir."
    }
  ]
}

{
