      "steps": [
        {
          "no": 1,
          "action": "Transmit continuous profile data with values [V1, V2, V3] and distances [D1, D2, D3].",
          "expected": "OBU accepts the data."
        },
        {
          "no": 2,
          "action": "Query the active profile value at distance 0 from the start of the new data.",
          "expected": "The active value is PrevData (previously received data applies over the first distance D1)."
