          "action": "Query the active profile value at distance D1.",
          "expected": "The active value is V1."
        },
        {
          "no": 4,
          "action": "Query the active profile value at distance D1 + D2.",
          "expected": "The active value is V2."
        },
        {
          "no": 5,
